     8	import EventKit
     9	import SwiftUI
    10	
    11	struct ContentView: View {
    12	    // MARK: Internal
    13	
    14	    var body: some View {
    15	        NavigationViewWrapper {
    16	            reminderList
    17	        }
    18	        .task {
    19	            await reminderStore.load()
    20	        }
    21	        .onChange(of: scenePhase) { _, newPhase in
    22	            if newPhase == .active {
    23	                Task {
    24	                    await reminderStore.load()
    25	                }
    26	            }
    27	        }
    28	    }
    29	
    30	    // MARK: Private
    31	
    32	    @Environment(ReminderStore.self) private var reminderStore
    33	    @Environment(\.scenePhase) private var scenePhase
    34	
    35	    private var visibleReminders: [VisibleReminder] {
    36	        let now = Date()
    37	        let calendar = Calendar.current
    38	        return reminderStore.reminders
    39	            .compactMap { reminder -> VisibleReminder? in
    40	                guard let status = dueStatus(
    41	                    dueDateComponents: reminder.dueDateComponents,
    42	                    isCompleted: reminder.isCompleted,
    43	                    now: now,
    44	                    calendar: calendar) else {
    45	                    return nil
    46	                }
    47	                let dueDate = reminder.dueDateComponents.flatMap { calendar.date(from: $0) } ?? .distantFuture
    48	                return VisibleReminder(reminder: reminder, status: status, dueDate: dueDate)
    49	            }
    50	            .sorted { $0.dueDate < $1.dueDate }
    51	    }
    52	
    53	    @ViewBuilder
    54	    private var reminderList: some View {
    55	        switch reminderStore.accessStatus {
    56	        case .notDetermined:
    57	            ProgressView("Loading reminders…")
    58	        case .denied:
    59	            ContentUnavailableView(
    60	                "Reminders access denied",
    61	                systemImage: "bell.slash",
    62	                description: Text("Enable Reminders access in Settings."))
    63	        case .authorized:
    64	            if visibleReminders.isEmpty {
    65	                ContentUnavailableView("No overdue or due-today reminders", systemImage: "checkmark.circle")
    66	            } else {
    67	                List {
    68	                    ForEach(visibleReminders, id: \.reminder.calendarItemIdentifier) { visible in
    69	                        ReminderRow(visible: visible)
    70	                    }
    71	                }
    72	                #if os(macOS)
    73	                .navigationSplitViewColumnWidth(min: 180, ideal: 200)
    74	                #endif
    75	            }
    76	        }
    77	    }
    78	}
    79	
    80	private struct VisibleReminder {
    81	    let reminder: EKReminder
    82	    let status: DueStatus
    83	    let dueDate: Date
    84	}
    85	
    86	private struct ReminderRow: View {
    87	    let visible: VisibleReminder
    88	
    89	    var body: some View {
    90	        VStack(alignment: .leading) {
    91	            Text(visible.reminder.title ?? "Untitled")
    92	            Text(visible.dueDate, format: Date.FormatStyle(date: .numeric, time: .standard))
    93	                .font(.caption)
    94	        }
    95	        .foregroundStyle(visible.status == .overdue ? Color.red : Color.primary)
    96	    }
    97	}
    98	
    99	private struct NavigationViewWrapper<Content: View>: View {
   100	    let content: () -> Content
   101	
   102	    var body: some View {
   103	        #if os(macOS)
   104	            NavigationSplitView {
   105	                content()
   106	            } detail: {
   107	                Text("Select a reminder")
   108	            }
   109	        #else
   110	            content()
   111	        #endif
   112	    }
   113	}
   114	
   115	#Preview {
   116	    ContentView()
   117	        .environment(ReminderStore())
   118	}
